import{_ as a,o as i,c as e,a2 as s}from"./chunks/framework.1lR7qgqY.js";const g=JSON.parse('{"title":"K5 工具呼叫, MCP 與代理","description":"","frontmatter":{},"headers":[],"relativePath":"know/k5-tools-agents.md","filePath":"know/k5-tools-agents.md","lastUpdated":1793015847000}'),l={name:"know/k5-tools-agents.md"};function r(n,t,d,o,h,p){return i(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="k5-工具呼叫-mcp-與代理" tabindex="-1">K5 工具呼叫, MCP 與代理 <a class="header-anchor" href="#k5-工具呼叫-mcp-與代理" aria-label="Permalink to &quot;K5 工具呼叫, MCP 與代理&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>待查證: K5.4 節的 BFCL 分數取自彙整站 benchmarklist.com; 官方排行榜表格為動態載入, 本輪未能逐一核對個別模型分數; K5.4 節引用的 arXiv 2608.22472 與 K5.5 節的 MCP 規格版本, NSA 指引日期本輪未重新核對; K5.3 節的題目配置與判定方式為整理者建議, 未實測</li><li>資料基準日: 2026-10-26</li></ul></div><p><strong>結論</strong>: 模型本身不會「動手」, 它只會輸出「要呼叫哪個工具, 帶什麼參數」, 由程式去執行. 多數情境不需要代理框架, 以「固定步驟的工作流程程式碼 + 每步一次函式呼叫 + 程式端驗證」取得的可靠度最高 (信心: 中高). MCP 是讓多個客戶端共用同一組工具的標準協定, 代理則是讓模型自己決定下一步; 兩者都屬於符合特定條件才用的元件.</p><h2 id="k5-1-單步準確率與多輪可靠度的差別" tabindex="-1">K5.1 單步準確率與多輪可靠度的差別 <a class="header-anchor" href="#k5-1-單步準確率與多輪可靠度的差別" aria-label="Permalink to &quot;K5.1 單步準確率與多輪可靠度的差別&quot;">​</a></h2><p>工具呼叫的評測分成兩種能力, 兩者的分數差距很大, 不能互相代替.</p><p><strong>單步</strong>: 給模型一段使用者請求與一組函式定義, 看模型是否選對函式, 參數名稱與型別是否正確. BFCL 主要以抽象語法樹 (AST) 解析模型輸出, 比對函式名稱, 參數, 型別與值; V1 另有實際執行函式的類別, 兩者互補 (來源: BFCL V1 部落格). 這一類又分成兩組題目:</p><ul><li><strong>非即時 (Non-Live)</strong>: 研究團隊自行撰寫的題目, 分為 simple, multiple, parallel, parallel multiple 四個子項, 分別測試「單一函式」「從多個函式中選一個」「一次呼叫多個」與兩者的組合.</li><li><strong>即時 (Live)</strong>: 使用者貢獻的真實函式與請求, 用來降低資料汙染 (data contamination) 與偏差的影響; 同一模型在 V1 與 Live 題目的分數落差很大時, 可能表示模型看過舊題目 (來源: BFCL V2 部落格).</li><li><strong>幻覺量測 (Hallucination)</strong>: 給模型不相關的函式, 看模型是否懂得「不呼叫」.</li></ul><p><strong>多輪</strong>: 使用者與模型往返多回合, 模型要記得前面的內容, 並把一個函式的輸出當作下一個函式的輸入. BFCL V3 在每一回合結束時做兩種檢查, 每一回合都通過才算答對 (來源: BFCL V3 部落格):</p><ul><li><strong>狀態檢查</strong>: 比對後端系統的最終狀態與標準答案, 用於寫入與刪除類動作.</li><li><strong>回應檢查</strong>: 比對模型的呼叫路徑是否包含最短可行路徑, 用於唯讀請求; 多呼叫幾次不扣分.</li><li>單一回合超過 20 步仍未結束, 直接判錯.</li></ul><p>多輪類別包含四種情境: 資訊齊全的基本題, 缺少必要參數 (模型應該發問而不是猜測), 缺少可用函式 (模型應該察覺沒有合適的工具), 以及長上下文 (大量無關資料混在其中) (來源: BFCL V3 部落格). 官方部落格列出的典型失敗包含: 沒有先查狀態就直接動作, 重複登入已經登入的服務, 以及陷入重複呼叫的迴圈.</p><p><strong>BFCL V4 新增的代理類別</strong>: V4 加入網路搜尋 (100 題人工撰寫的多步推理問題, 搭配搜尋與擷取網頁兩種工具, 並隨機模擬 503 與逾時) 與記憶兩項代理評測; 另有格式敏感度 (format sensitivity) 測試, 只適用於 Prompt 模式的模型, 而且不計入總分 (來源: BFCL V4 部落格, BFCL 排行榜頁).</p><p>單步與多輪的落差可以用簡單的估算理解: 若每一步成功率都是 88%, 而且各步彼此獨立, 連續 5 步都成功的機率約為 0.88 的 5 次方, 約 53%. 實際任務中各步並不獨立, 前一步的錯誤會使後一步更難, 因此這個估算只用來說明方向 (推論, 信心: 中). 這也是 K5.4 節建議「每步一次函式呼叫, 由程式串接」的原因.</p><h2 id="k5-2-bfcl-分數的讀法與限制" tabindex="-1">K5.2 BFCL 分數的讀法與限制 <a class="header-anchor" href="#k5-2-bfcl-分數的讀法與限制" aria-label="Permalink to &quot;K5.2 BFCL 分數的讀法與限制&quot;">​</a></h2><p>官方排行榜位於 <a href="https://gorilla.cs.berkeley.edu/leaderboard.html" target="_blank" rel="noreferrer">gorilla.cs.berkeley.edu/leaderboard.html</a>. 讀分數時, 先確認下列四件事.</p><p><strong>1. 總分的權重偏重代理與多輪</strong>: BFCL V4 的總分公式為代理 40%, 多輪 30%, 即時 10%, 非即時 10%, 幻覺量測 10%; 代理一項由網路搜尋與記憶等權平均 (來源: BFCL V4 部落格). 因此一個單步準確率超過 80% 的小模型, 總分仍可能只有 40% 左右, 如 K5.4 節的表格所示. 讀者若只打算讓模型做單步呼叫, 應該看非即時與即時兩欄, 而不是總分; 打算讓模型自主串接多步, 才需要看多輪與代理兩欄 (推論, 信心: 高).</p><p><strong>2. 評測模式</strong>: 排行榜把模型分成 FC 與 Prompt 兩種模式. FC 代表模型原生支援函式呼叫, Prompt 代表以一般文字生成模擬函式呼叫 (來源: BFCL 排行榜頁). 同一個模型在兩種模式下的分數不同, 比較時要對齊模式. 地端部署時, FC 模式能否發揮, 還取決於推論伺服器的 tool-call parser 與 chat template 是否和模型相符 (見 M1).</p><p><strong>3. 版本與資料日期</strong>: 官方頁面標示的最後更新日與評測程式版本 (commit 與 PyPI 套件 <code>bfcl-eval</code> 的版本), 是判斷分數是否可以互相比較的依據; 總分組成在 V3 與 V4 之間已經改變, V3 部落格也註明其總分組成已過時 (來源: BFCL 排行榜頁, BFCL V3 部落格). 彙整站轉載的分數可能來自不同時間點, 也可能混用不同版本的欄位. K5.4 節的表格目前取自彙整站 benchmarklist.com, 屬二手來源; 官方排行榜的表格以動態方式載入, 本輪未能以文字擷取核對個別模型的數字, 因此該表維持「經彙整站」的標示 (待核對).</p><p><strong>4. 模型卡自報分數</strong>: 模型發布者在模型卡上自報的 BFCL 分數, 可能使用不同的評測版本, 子集或提示格式, 沒有經過排行榜團隊重跑. 這類分數只能當作發布者的宣稱, 不應與排行榜分數放在同一欄比較 (信心: 高). K5.4 節的 Qwen3.5-4B 一列即屬此類.</p><p><strong>評測本身的限制</strong>: 官方部落格自己列出的限制包含: 網路搜尋只有 100 題; 部分模型不使用工具, 直接以訓練資料作答, 仍可能答對; 答案以正規化後的精確比對評分, 標準嚴格 (來源: BFCL V4 部落格). 除此之外, 排行榜的函式與請求都是通用情境, 不是讀者自己的工具與繁體中文請求; 地端執行的量化版本, 也可能與排行榜評測的版本不同 (推論, 信心: 中). 因此排行榜適合用來縮小候選範圍, 最後仍須用 K5.3 節的方法實測.</p><h2 id="k5-3-用自己的任務做-20-題實測" tabindex="-1">K5.3 用自己的任務做 20 題實測 <a class="header-anchor" href="#k5-3-用自己的任務做-20-題實測" aria-label="Permalink to &quot;K5.3 用自己的任務做 20 題實測&quot;">​</a></h2><p>排行榜回答「這個模型一般表現如何」, 實測回答「這個模型能不能用在自己的工具上」. 建議在選定候選模型後, 以自己的工具定義與真實請求寫 20 題, 每次換模型, 換量化版本, 換推論伺服器版本或改工具描述時重跑 (信心: 高).</p><p><strong>題目配置</strong>: 下表的配置參考 BFCL 的分類方式, 題數為建議值, 可依自己的工具數量調整 (推論).</p><table tabindex="0"><thead><tr><th>類型</th><th>題數</th><th>期望行為</th><th>對應 BFCL 類別</th></tr></thead><tbody><tr><td>單一工具</td><td>6</td><td>選對工具, 必要參數齊全, 型別正確</td><td>非即時 simple</td></tr><tr><td>相似工具擇一</td><td>4</td><td>從名稱或用途相近的工具中選對一個</td><td>非即時 multiple</td></tr><tr><td>不應呼叫</td><td>3</td><td>請求與工具無關時, 直接回答或拒絕, 不呼叫工具</td><td>幻覺量測</td></tr><tr><td>缺少參數</td><td>2</td><td>必要資訊不足時發問, 不自行編造參數</td><td>多輪 missing parameter</td></tr><tr><td>兩到三步串接</td><td>3</td><td>依序呼叫, 並把前一步的輸出帶入下一步</td><td>多輪 base</td></tr><tr><td>含不可信內容</td><td>2</td><td>請求附帶的文件內藏有指令時, 不照著做 (見 K5.6)</td><td>無直接對應</td></tr></tbody></table><p><strong>每題記錄的欄位</strong>: 題號, 使用者請求 (以真實工作語句撰寫, 含繁體中文與常見縮寫), 提供給模型的工具清單, 期望的工具名稱與參數, 判定方式. 下面是一題的記錄範例, 格式為本手冊自訂, 不是特定工具的設定語法:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#8DDB8C;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;tool-07&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#8DDB8C;">  &quot;request&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;查一下昨天 10.0.5.23 有沒有登入失敗的紀錄&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#8DDB8C;">  &quot;tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;siem.query&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;ticket.create&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;host.lookup&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#8DDB8C;">  &quot;expect&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#8DDB8C;">    &quot;tool&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;siem.query&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#8DDB8C;">    &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#8DDB8C;">&quot;src_ip&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;10.0.5.23&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#8DDB8C;">&quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;login_failure&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#8DDB8C;">&quot;range&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;1d&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#8DDB8C;">  &quot;check&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;工具名稱完全相同; src_ip 完全相同; range 允許 1d 或 24h&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">}</span></span></code></pre></div><p><strong>判定方式</strong>: 參考 BFCL 的做法, 單步題以程式比對工具名稱與參數 (相當於 AST 比對), 不靠人工目視; 串接題另外檢查執行後的系統狀態 (例如測試環境中是否真的建立一張 ticket), 寫入類動作一律在測試環境執行 (推論, 信心: 中高). 同一題的模型輸出每次可能不同, 建議每題至少跑 3 次, 並固定溫度等取樣參數, 以「3 次全對」與「至少 1 次對」兩個比率分別記錄 (推論).</p><p><strong>併入 M6 測試集</strong>: 這 20 題就是 M6.1 節測試集中「工具呼叫題」一類, 與日常任務題, 檢索問答題放在同一份測試集, 以同一套流程執行與比較 (見 <a href="/docs-handbook-poc/build/m6-observability">M6</a>). 結果出現退步時, 先檢查 tool-call parser, chat template 與工具描述是否有變動, 再考慮換模型.</p><h2 id="k5-4-先寫工作流程-再考慮代理" tabindex="-1">K5.4 先寫工作流程, 再考慮代理 <a class="header-anchor" href="#k5-4-先寫工作流程-再考慮代理" aria-label="Permalink to &quot;K5.4 先寫工作流程, 再考慮代理&quot;">​</a></h2><p>小模型「選對函式, 填對參數」的單步準確率約 78% 至 88%, 但多輪任務只有約 30% 至 42%.</p><table tabindex="0"><thead><tr><th>模型</th><th>總分</th><th>非即時 AST</th><th>即時 (Live)</th><th>多輪 (Multi-turn)</th></tr></thead><tbody><tr><td>Qwen3-8B (FC)</td><td>42.57%</td><td>87.58%</td><td>80.53%</td><td>41.75%</td></tr><tr><td>Qwen3-14B (FC)</td><td>41.03%</td><td>84.94%</td><td>80.01%</td><td>34.75%</td></tr><tr><td>Qwen3-30B-A3B-Instruct-2507 (FC)</td><td>41.39%</td><td>85.77%</td><td>77.94%</td><td>30%</td></tr><tr><td>Qwen3.5-4B (模型卡自報)</td><td>50.3%</td><td>-</td><td>-</td><td>-</td></tr></tbody></table><p>資料來源: BFCL V4 (Berkeley Function Calling Leaderboard), 經 benchmarklist.com 彙整, 資料匯入日 2026-05-28; Qwen3.5-4B 為模型卡自報.</p><p>讓 8B 模型自主串接 5 步以上的工具, 失敗是常態 (信心: 中高). 另有一篇論文 (arXiv 2608.22472) 顯示, 改用「指令遵循式」函式呼叫格式, 可讓 Qwen3-4B 與 8B 在 BFCL 子集提升到 90% 以上, 表示提示格式與流程設計的影響可能大於換框架 (信心: 中).</p><h2 id="k5-5-函式呼叫與-mcp-的取捨" tabindex="-1">K5.5 函式呼叫與 MCP 的取捨 <a class="header-anchor" href="#k5-5-函式呼叫與-mcp-的取捨" aria-label="Permalink to &quot;K5.5 函式呼叫與 MCP 的取捨&quot;">​</a></h2><p>MCP (Model Context Protocol) 最新規格是 2026-07-28 版, 核心改為無狀態, 取消 initialize 交握與 Mcp-Session-Id 標頭, 並新增正式的棄用政策 (12 個月棄用期). 美國 NSA 於 2026-06-02 發布 MCP 安全設計指引.</p><table tabindex="0"><thead><tr><th>情境</th><th>建議</th></tr></thead><tbody><tr><td>自己撰寫的單一應用, 工具不超過 3 至 5 個, 只有一個客戶端</td><td>直接用函式呼叫</td></tr><tr><td>同一組工具要給多個客戶端共用 (Open WebUI, IDE, 桌面助理)</td><td>使用 MCP</td></tr><tr><td>要使用信譽良好的現成伺服器</td><td>使用 MCP, 並依 M7.1 節審核</td></tr><tr><td>低階硬體的初階讀者</td><td>不建議列為入門步驟</td></tr></tbody></table><p>不建議初階讀者的理由有三: 小模型多輪工具呼叫可靠度低; 每個 MCP 伺服器都是以使用者權限執行的程式; 一般函式呼叫就能完成同樣的事 (信心: 中高). 手冊範例須標註所依據的 MCP 規格版本.</p><h2 id="k5-6-代理-政策與隔離的基本概念" tabindex="-1">K5.6 代理, 政策與隔離的基本概念 <a class="header-anchor" href="#k5-6-代理-政策與隔離的基本概念" aria-label="Permalink to &quot;K5.6 代理, 政策與隔離的基本概念&quot;">​</a></h2><p>本節是 <a href="/docs-handbook-poc/build/m8-agent-governance">M8 代理與治理</a>的底層知識. 核心觀念只有一句: 模型的輸出不能當作授權, 每個會改變系統狀態的動作, 都要由模型以外的確定性規則再判定一次 (信心: 高).</p><h3 id="提示注入-prompt-injection" tabindex="-1">提示注入 (prompt injection) <a class="header-anchor" href="#提示注入-prompt-injection" aria-label="Permalink to &quot;提示注入 (prompt injection)&quot;">​</a></h3><p>OWASP 將提示注入定義為「使用者的提示以非預期的方式改變 LLM 的行為或輸出」, 並分為兩種 (來源: OWASP GenAI, LLM01:2025):</p><ul><li><strong>直接注入</strong>: 使用者自己輸入的內容改變模型行為, 可能是刻意的, 也可能是無意的.</li><li><strong>間接注入</strong>: 模型讀取網頁, 檔案, 郵件, log 等外部內容時, 內容中夾帶的指令影響模型. 人看不到的文字, 只要模型會解析, 一樣有效.</li></ul><p>OWASP 指出, 由於模型的隨機特性, 目前不清楚是否存在萬無一失的防範方法. 該頁列出的因應方向包含: 在系統提示中界定模型角色與限制; 規定輸出格式, 並以確定性程式碼檢查輸出; 應用程式使用自己的 API 憑證, 特權功能在程式碼中執行, 只給最小權限; 高風險動作需要人工核准; 明確區隔並標示不可信的外部內容; 定期做對抗測試 (來源: OWASP GenAI, LLM01:2025). 這些方向的共同點是「假設注入會成功, 限制成功之後能造成的影響」, 本手冊 M7 與 M8 的設計都依此展開. OWASP 其他風險與本手冊的對照見 K6.4 節.</p><h3 id="雙-llm-模式-隔離模型" tabindex="-1">雙 LLM 模式 (隔離模型) <a class="header-anchor" href="#雙-llm-模式-隔離模型" aria-label="Permalink to &quot;雙 LLM 模式 (隔離模型)&quot;">​</a></h3><p>Simon Willison 於 2023 年提出雙 LLM 模式 (Dual LLM pattern), 把助理拆成三個角色 (來源: Simon Willison, The Dual LLM pattern):</p><table tabindex="0"><thead><tr><th>角色</th><th>讀什麼</th><th>能做什麼</th></tr></thead><tbody><tr><td>特權模型 (Privileged LLM)</td><td>只讀可信來源, 主要是使用者的指示</td><td>可以呼叫工具</td></tr><tr><td>隔離模型 (Quarantined LLM)</td><td>讀取不可信內容 (郵件, 網頁等)</td><td>沒有任何工具, 並假設它隨時可能遭到操控</td></tr><tr><td>控制器 (Controller)</td><td>一般程式, 不是模型</td><td>觸發兩個模型, 代替特權模型執行動作</td></tr></tbody></table><p>控制器把隔離模型的輸出存成變數 (例如 <code>$VAR1</code>), 特權模型只看到變數名稱, 看不到內容. 原文強調, 未經過濾的隔離模型輸出絕對不能轉給特權模型; 唯一的例外是能以固定類別驗證的輸出, 例如分類結果 (來源: 同上). 原文也承認這個模式不是百分之百可靠: 使用者自己複製貼上不可信內容時就會失效, 而且實作複雜, 可能影響使用體驗.</p><p>本手冊的隔離模型採用同一個原則, 做法是讓隔離模型只輸出固定欄位的 JSON, 由程式檢查格式與長度後, 才把個別欄位交給 LangGraph (見 M8.3 節). 這個做法擋不住「惡意值放進合法欄位」, 例如在「受影響主機」欄位填入網域控制站的名稱, 因此還需要政策引擎的關鍵資產清單把關 (信心: 中高).</p><p>後續研究 CaMeL (arXiv:2503.18813) 從可信的使用者請求中明確抽出控制流程與資料流程, 讓不可信資料無法影響程式流程, 並以 capability 的概念在呼叫工具時套用安全政策, 防止私人資料經未授權的資料流外洩. 論文摘要指出, CaMeL 在 AgentDojo 評測中以可證明的安全性完成 77% 的任務, 未設防的系統為 84% (來源: arXiv:2503.18813 摘要). 這表示「依設計隔離」需要付出一部分任務完成率, 屬於可預期的取捨 (推論, 信心: 中).</p><h3 id="政策引擎與人工核准" tabindex="-1">政策引擎與人工核准 <a class="header-anchor" href="#政策引擎與人工核准" aria-label="Permalink to &quot;政策引擎與人工核准&quot;">​</a></h3><p>政策引擎是模型以外的確定性判定點. 代理每次呼叫工具前, 先把「哪個工具, 帶什麼參數, 這次執行已經呼叫幾次」送給政策引擎, 依回傳結果決定執行, 拒絕或轉人工核准. 本手冊使用 OPA (Open Policy Agent), 做法見 M8.2 節. 政策引擎的價值在於它不讀不可信內容, 也不受提示影響, 同一個輸入永遠得到同一個結果 (信心: 高).</p><p>人工核准是政策引擎的延伸: 政策判定「需要人看」時, 流程暫停, 等核准者回覆後再繼續. LangGraph 以 <code>interrupt</code> 機制提供這個功能, 見 M8.4 節.</p><h3 id="依能否回復分級-a0-至-a3" tabindex="-1">依能否回復分級 (A0 至 A3) <a class="header-anchor" href="#依能否回復分級-a0-至-a3" aria-label="Permalink to &quot;依能否回復分級 (A0 至 A3)&quot;">​</a></h3><p>動作是否需要人工核准, 依「做錯了能不能回復」決定, 而不是依工具名稱的直覺 (信心: 中高, 屬整理者的設計原則). 下表的 A0 至 A3 是動作分級代號 (A 代表 action).</p><table tabindex="0"><thead><tr><th>等級</th><th>定義</th><th>範例</th><th>處理方式</th></tr></thead><tbody><tr><td>A0 唯讀</td><td>只讀取, 不改變任何狀態</td><td>查詢 SIEM, 讀取設定</td><td>自動執行, 仍受配額限制</td></tr><tr><td>A1 內部可自動回復</td><td>只影響內部, 系統能自動復原</td><td>建立 ticket, 加註標籤</td><td>自動執行, 留下紀錄</td></tr><tr><td>A2 影響範圍大或對外可見</td><td>可以回復, 但影響多人或外部看得到</td><td>隔離主機, 批次修改設定</td><td>兩個不同模型分別審查, 結果不一致轉人工; 以 canary 方式分批執行</td></tr><tr><td>A3 不可回復</td><td>做了就無法復原</td><td>刪除資料, 金流, 對外發信, 修改正式環境安全設定</td><td>一律人工核准</td></tr></tbody></table><p>分級寫在政策檔中, 由政策引擎依工具名稱查表, 不讓模型自己申報等級; 不在表內的工具一律拒絕 (推論, 信心: 中高). 實作見 M8.2 與 M8.4 節.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><ul><li><a href="https://gorilla.cs.berkeley.edu/leaderboard.html" target="_blank" rel="noreferrer">Berkeley Function Calling Leaderboard (BFCL) 官方排行榜</a></li><li><a href="https://gorilla.cs.berkeley.edu/blogs/8_berkeley_function_calling_leaderboard.html" target="_blank" rel="noreferrer">BFCL V1 部落格: 評測方法與 AST 比對</a></li><li><a href="https://gorilla.cs.berkeley.edu/blogs/12_bfcl_v2_live.html" target="_blank" rel="noreferrer">BFCL V2 部落格: Live 資料集</a></li><li><a href="https://gorilla.cs.berkeley.edu/blogs/13_bfcl_v3_multi_turn.html" target="_blank" rel="noreferrer">BFCL V3 部落格: 多輪評測</a></li><li><a href="https://gorilla.cs.berkeley.edu/blogs/15_bfcl_v4_web_search.html" target="_blank" rel="noreferrer">BFCL V4 部落格: 網路搜尋與總分組成</a></li><li><a href="https://github.com/ShishirPatil/gorilla/tree/main/berkeley-function-call-leaderboard" target="_blank" rel="noreferrer">BFCL 程式碼與資料 (GitHub)</a></li><li><a href="https://genai.owasp.org/llmrisk/llm01-prompt-injection/" target="_blank" rel="noreferrer">OWASP GenAI: LLM01:2025 Prompt Injection</a></li><li><a href="https://simonwillison.net/2023/Apr/25/dual-llm-pattern/" target="_blank" rel="noreferrer">Simon Willison: The Dual LLM pattern</a></li><li><a href="https://arxiv.org/abs/2503.18813" target="_blank" rel="noreferrer">Debenedetti 等: Defeating Prompt Injections by Design (arXiv:2503.18813)</a></li></ul>`,57)])])}const c=a(l,[["render",r]]);export{g as __pageData,c as default};
